  "social.noService": { vi: "Không tìm thấy dịch vụ", en: "No services found" },
  "social.guide": { vi: "Hướng dẫn", en: "Guide" },
  "social.guideFor": { vi: "Hướng dẫn dùng", en: "How to use" },
  "social.gotIt": { vi: "Đã hiểu", en: "Got it" },
  "social.integrationTip": { vi: "Mẹo: mô tả tích hợp này trong prompt khi tạo/sửa app để Larkwave tự sinh code gọi API, sau đó dán API key của bạn vào phần cấu hình.", en: "Tip: describe this integration in your prompt when creating/editing an app so Larkwave auto-generates the API-calling code, then paste your API key into the config." },
  "social.intg.stripe.desc": { vi: "Nhận thanh toán, đăng ký và hoá đơn trực tuyến.", en: "Accept payments, subscriptions, and invoices online." },
  "social.intg.stripe.howto": { vi: "Tạo Secret Key trong Dashboard Stripe, thêm vào cấu hình app (biến môi trường STRIPE_SECRET_KEY) rồi gọi Stripe API để tạo Checkout Session hoặc PaymentIntent.", en: "Create a Secret Key in the Stripe Dashboard, add it to your app config (STRIPE_SECRET_KEY env var), then call the Stripe API to create a Checkout Session or PaymentIntent." },
  "social.intg.salesforce.desc": { vi: "Đồng bộ khách hàng tiềm năng và dữ liệu CRM.", en: "Sync leads and CRM data." },
  "social.intg.salesforce.howto": { vi: "Tạo Connected App trong Salesforce để lấy Client ID/Secret, xác thực qua OAuth2, sau đó gọi REST API (/services/data) từ code của app.", en: "Create a Connected App in Salesforce to get a Client ID/Secret, authenticate via OAuth2, then call the REST API (/services/data) from your app code." },
  "social.intg.slack.desc": { vi: "Gửi thông báo và tin nhắn vào kênh Slack.", en: "Send notifications and messages to a Slack channel." },
  "social.intg.slack.howto": { vi: "Tạo Incoming Webhook hoặc Bot Token trong Slack App, lưu vào cấu hình app, rồi POST nội dung tới webhook URL để gửi tin nhắn.", en: "Create an Incoming Webhook or Bot Token in your Slack App, save it to your app config, then POST content to the webhook URL to send messages." },
  "social.intg.notion.desc": { vi: "Đọc/ghi dữ liệu vào database Notion.", en: "Read/write data to a Notion database." },
  "social.intg.notion.howto": { vi: "Tạo Internal Integration trong Notion, lấy Integration Token, share database với integration, rồi gọi Notion API (/v1/pages, /v1/databases).", en: "Create an Internal Integration in Notion, get the Integration Token, share the database with the integration, then call the Notion API (/v1/pages, /v1/databases)." },
  "social.intg.google-calendar.desc": { vi: "Tạo và quản lý sự kiện lịch.", en: "Create and manage calendar events." },
  "social.intg.google-calendar.howto": { vi: "Bật Google Calendar API trong Google Cloud Console, tạo OAuth credentials, xác thực người dùng, rồi gọi events.insert/list để thao tác sự kiện.", en: "Enable the Google Calendar API in Google Cloud Console, create OAuth credentials, authenticate the user, then call events.insert/list to manage events." },
  "social.intg.google-drive.desc": { vi: "Lưu trữ và truy xuất tệp trên Drive.", en: "Store and retrieve files on Drive." },
  "social.intg.google-drive.howto": { vi: "Bật Drive API, dùng OAuth2 để cấp quyền, rồi gọi files.create/list/get với access token để upload và đọc tệp.", en: "Enable the Drive API, use OAuth2 to grant access, then call files.create/list/get with an access token to upload and read files." },
  "social.intg.gmail.desc": { vi: "Gửi email giao dịch qua tài khoản Gmail.", en: "Send transactional email via a Gmail account." },
  "social.intg.gmail.howto": { vi: "Bật Gmail API trong Google Cloud, xác thực OAuth2 với scope gmail.send, rồi gọi users.messages.send với nội dung email đã mã hoá base64.", en: "Enable the Gmail API in Google Cloud, authenticate via OAuth2 with the gmail.send scope, then call users.messages.send with base64-encoded email content." },
  "social.intg.google-sheets.desc": { vi: "Đọc/ghi bảng tính như một cơ sở dữ liệu nhẹ.", en: "Read/write spreadsheets as a lightweight database." },
  "social.intg.google-sheets.howto": { vi: "Bật Sheets API, dùng Service Account hoặc OAuth2, share sheet với tài khoản, rồi gọi spreadsheets.values.get/update để đọc ghi dữ liệu.", en: "Enable the Sheets API, use a Service Account or OAuth2, share the sheet with the account, then call spreadsheets.values.get/update to read and write data." },
  "social.intg.hubspot.desc": { vi: "Quản lý contact, deal và marketing.", en: "Manage contacts, deals, and marketing." },
  "social.intg.hubspot.howto": { vi: "Tạo Private App trong HubSpot để lấy Access Token, thêm vào cấu hình, rồi gọi CRM API (/crm/v3/objects) để tạo/cập nhật contact và deal.", en: "Create a Private App in HubSpot to get an Access Token, add it to your config, then call the CRM API (/crm/v3/objects) to create/update contacts and deals." },
  "social.intg.openai.desc": { vi: "Thêm tính năng AI: chat, tóm tắt, sinh nội dung.", en: "Add AI features: chat, summarization, content generation." },
  "social.intg.openai.howto": { vi: "Lấy API Key tại platform.openai.com, lưu vào biến môi trường OPENAI_API_KEY, rồi gọi endpoint chat/completions từ backend của app.", en: "Get an API Key at platform.openai.com, store it in the OPENAI_API_KEY env var, then call the chat/completions endpoint from your app backend." },
  "social.intg.webhook.desc": { vi: "Nhận hoặc gửi sự kiện realtime qua HTTP.", en: "Receive or send realtime events over HTTP." },
  "social.intg.webhook.howto": { vi: "Cấu hình một URL nhận trong app, hoặc POST payload JSON tới URL đích khi có sự kiện. Xác thực bằng secret/signature trong header.", en: "Configure a receiving URL in your app, or POST a JSON payload to the target URL when an event occurs. Verify with a secret/signature in the header." },
  "social.intg.rest-api.desc": { vi: "Kết nối tới bất kỳ dịch vụ REST nào.", en: "Connect to any REST service." },
  "social.intg.rest-api.howto": { vi: "Khai báo base URL và API key của dịch vụ trong cấu hình app, rồi dùng fetch/axios để gọi các endpoint với header Authorization phù hợp.", en: "Declare the service's base URL and API key in your app config, then use fetch/axios to call the endpoints with the appropriate Authorization header." },
  "wcomp.larkReloginBtn": { vi: "Đăng nhập lại Lark (CMS) trên máy", en: "Log in to Lark (CMS) again on the computer" },
