  "ui.composer.splitServices": { vi: "Tách thành dịch vụ riêng (mỗi phần 1 thư mục + 1 cổng, chạy song song)", en: "Split into separate services (each part its own folder + port, running in parallel)" },
  "ui.composer.multiServiceOn": { vi: "Workspace nhiều dịch vụ: home / api / cms mỗi cái chạy trên cổng riêng, tự tiêm URL API cho frontend.", en: "Multi-service workspace: home / api / cms each run on their own port, with the API URL auto-injected into the frontend." },
