  "ui.composer.framework": { vi: "Framework", en: "Framework" },
  "ui.composer.ui": { vi: "Giao diện", en: "UI" },
  "ui.composer.techOther": { vi: "Công nghệ khác (vd PHP, Express, Prisma, Postgres…)", en: "Other tech (e.g. PHP, Express, Prisma, Postgres…)" },
  "ui.composer.techHint": { vi: "Để \"Tự động\" = ngăn xếp đẹp nhất, full-stack: React + TypeScript + Ant Design + Tailwind (frontend) · Node + SQLite (backend/CSDL). Preview cục bộ chạy tốt nhất với React / Vue / Next.js; chọn PHP/Python thì cần \"Chạy trên Server\" để xem.", en: "Leave it on \"Auto\" = the best full-stack stack: React + TypeScript + Ant Design + Tailwind (frontend) · Node + SQLite (backend/DB). Local preview works best with React / Vue / Next.js; picking PHP/Python requires \"Run on Server\" to view." },
  "ui.composer.cloneWebsite": { vi: "Sao chép từ website (tuỳ chọn)", en: "Clone from a website (optional)" },
  "ui.composer.cloneWebsitePlaceholder": { vi: "Dán URL trang muốn sao chép, vd: https://luyenphongvan.online", en: "Paste the URL of the site to clone, e.g. https://luyenphongvan.online" },
  "ui.composer.cloneWebsiteHint": { vi: "Hệ thống tự mở trang và chụp lại màn hình để AI nhìn thấy bố cục, màu và font thật — bạn không cần đính kèm ảnh. Nếu trang chặn hoặc chụp lỗi thì vẫn dựng theo phần chữ đọc được.", en: "The system opens the page and screenshots it for you, so the AI sees the real layout, colours and fonts — no need to attach an image. If the page blocks us or the capture fails, the build still uses the text it could read." },
  "ui.composer.preset": { vi: "Quy trình tạo app", en: "Build workflow" },
  "ui.preset.turbo": { vi: "Làm ngay", en: "Build now" },
  "ui.preset.balanced": { vi: "Cân bằng", en: "Balanced" },
  "ui.preset.thorough": { vi: "Kỹ (xem thiết kế trước)", en: "Thorough (review the design first)" },
  "ui.presetHint.turbo": { vi: "Bỏ qua bước phân tích + thiết kế, viết code ngay. Nhanh nhất, nhưng AI tự suy đoán cấu trúc — app dễ thiếu ý nếu mô tả còn sơ sài. Hợp khi mô tả đã rõ, hoặc khi sao chép một trang có sẵn.", en: "Skips the analysis + design steps and writes code straight away. Fastest, but the AI guesses the structure — a thin description can come back missing pieces. Best when your description is already clear, or when cloning an existing page." },
  "ui.presetHint.balanced": { vi: "Mặc định: AI phân tích yêu cầu và lên thiết kế trước khi viết code, rồi tự duyệt để bạn không phải chờ. Lâu hơn “Làm ngay” vài phút, đổi lại cấu trúc app chắc hơn.", en: "The default: the AI analyses the request and drafts a design before writing code, then approves it itself so you never wait. A few minutes slower than “Build now”, in exchange for a sounder structure." },
  "ui.presetHint.thorough": { vi: "AI DỪNG lại cho bạn xem và sửa bản thiết kế (các trang + dữ liệu) rồi mới sinh code. Kiểm soát cao nhất, nhưng lâu nhất — build nằm chờ tới khi bạn bấm duyệt.", en: "The AI STOPS so you can review and edit the design (pages + data) before any code is generated. The most control, and the slowest — the build waits until you approve it." },
  "ui.presetHintDesktop.thorough": { vi: "AI lập kế hoạch kỹ (các trang + dữ liệu) và giải thích trước khi viết code. Chắc tay nhất, nhưng lâu nhất. Trên máy không có bước dừng chờ bạn duyệt như trên web.", en: "The AI plans carefully (pages + data) and explains itself before writing code. The most solid option, and the slowest. On desktop there is no pause-for-approval step like on the web." },
  "ui.composer.presetCloneAuto": { vi: "Bạn đang sao chép từ URL nên hệ thống chọn sẵn “Làm ngay”: bước thiết kế sẽ tự nghĩ ra giao diện mới, ngược với việc chép cho giống trang gốc. Muốn đổi thì cứ chọn lại.", en: "You are cloning a URL, so “Build now” is preselected: the design step would invent a new interface, which works against copying the source page. Change it back any time." },
  "ui.composer.presetCloneWarn": { vi: "Đang sao chép từ URL: bước thiết kế sẽ tự nghĩ ra giao diện mới nên bản sao dễ lệch khỏi trang gốc. Chọn “Làm ngay” để bám sát trang gốc hơn.", en: "Cloning a URL: the design step invents a new interface, so the copy can drift from the source page. Pick “Build now” to stay closer to the original." },
