  "web.home.trackAuto": { vi: "Tự động", en: "Auto" },
  "web.home.trackHintWeb": { vi: "Website chạy thẳng trên trình duyệt — Larkwave tự build, deploy và cho xem preview live ngay. Mỗi web app còn tự kèm khả năng “Thêm vào màn hình chính” như một app điện thoại (PWA) + icon tự tạo theo màu bạn chọn.", en: "Websites run right in the browser — Larkwave auto-builds, deploys and shows a live preview instantly. Every web app also comes with an “Add to Home Screen” option like a phone app (PWA), plus an auto-generated icon in the color you pick." },
  "web.home.trackHintMobile": { vi: "Dự án Expo (React Native + TypeScript). Không có preview web — tải code về, chạy “npm install” rồi “npx expo start”, quét mã QR bằng app Expo Go trên điện thoại để xem trực tiếp trên iOS/Android.", en: "An Expo project (React Native + TypeScript). No web preview — download the code, run “npm install” then “npx expo start”, and scan the QR code with the Expo Go app on your phone to view it live on iOS/Android." },
  "web.home.trackHintExtension": { vi: "Tiện ích Chrome/Edge (Manifest V3). Tải code về → mở chrome://extensions → bật “Developer mode” → “Load unpacked” và chọn thư mục để cài. Không cần build, không có preview live.", en: "A Chrome/Edge extension (Manifest V3). Download the code → open chrome://extensions → enable “Developer mode” → “Load unpacked” and pick the folder to install. No build needed, no live preview." },
  "web.home.trackHintAuto": { vi: "AI tự đọc mô tả và chọn loại app phù hợp nhất. Nếu muốn deploy & preview ngay, hãy chọn Website.", en: "The AI reads your description and picks the best-fitting app type. If you want instant deploy & preview, choose Website." },
