  "web.pubc.featAiTitle": { vi: "AI chạy trên máy bạn", en: "AI runs on your machine" },
  "web.pubc.featAiDesc": { vi: "Dùng AI CLI (Claude/Grok/...) + gói của bạn để sinh code — chi phí gần như bằng 0, không tốn token của Larkwave.", en: "Use your AI CLI (Claude/Grok/...) + your own plan to generate code — near-zero cost, no Larkwave tokens used." },
  "web.pubc.featLarkTitle": { vi: "Lark × Agents toàn quyền", en: "Lark × Agents, full access" },
  "web.pubc.featLarkDesc": { vi: "Đăng nhập Lark bằng QR (tài khoản cá nhân) → AI thao tác với tư cách bạn trên mọi Base, Docs, Sheets, Wiki, Drive, tin nhắn. Tự động nạp Base.", en: "Sign in to Lark via QR (personal account) → AI acts as you across every Base, Docs, Sheets, Wiki, Drive and message. Auto-loads Bases." },
  "web.pubc.featBuildTitle": { vi: "Dựng app từ phân tích", en: "Build apps from analysis" },
  "web.pubc.featBuildDesc": { vi: "Từ một cuộc phân tích dữ liệu Lark, bấm một nút là ra brief app full-stack (schema + dữ liệu mẫu + phân tích) — chỉnh rồi build.", en: "From a Lark data analysis, one click produces a full-stack app brief (schema + sample data + analysis) — tweak, then build." },
  "web.pubc.featOfflineTitle": { vi: "Chạy offline-first", en: "Offline-first" },
  "web.pubc.featOfflineDesc": { vi: "Server lỗi vẫn xem được dữ liệu đã lưu trên máy + báo mất kết nối; mượt mạng lại tự đồng bộ.", en: "Even when the server is down you can view data saved locally plus an offline notice; it re-syncs automatically once you're back online." },
  "web.pubc.featUpdateTitle": { vi: "Tự cập nhật (code-push)", en: "Auto-update (code-push)" },
  "web.pubc.featUpdateDesc": { vi: "Cài một lần — giao diện tự cập nhật ở lần mở kế, không phải tải lại. Bản có thay đổi lõi sẽ báo tải bản mới.", en: "Install once — the UI updates itself the next time you open it, no re-download. Releases with core changes prompt you to download the new build." },
  "web.pubc.featSecTitle": { vi: "Bảo mật trên máy bạn", en: "Secure on your machine" },
  "web.pubc.featSecDesc": { vi: "Token AI/Lark được mã hoá (OS keychain) và lưu cục bộ — không rời khỏi máy bạn.", en: "AI/Lark tokens are encrypted (OS keychain) and stored locally — they never leave your machine." },
  "web.pubc.winStep1": { vi: "Tải bản Windows (.zip) bên trên.", en: "Download the Windows build (.zip) above." },
  "web.pubc.winStep2": { vi: "Giải nén, chạy Larkwave.exe (chưa ký số → bấm More info → Run anyway).", en: "Unzip and run Larkwave.exe (unsigned → click More info → Run anyway)." },
  "web.pubc.winStep3": { vi: "Cài AI CLI (Claude/Grok/...) + đăng nhập/key (hoặc dán trong app).", en: "Install an AI CLI (Claude/Grok/...) + sign in / add a key (or paste it in the app)." },
